import{_ as t,a0 as r,w as o,s as d,ao as n,I as h,a1 as e,A as a,x as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"Linux Shell 介紹：Bash、Zsh 和 Fish | LCTT x X-CMD","titleTemplate":false,"description":"Linux Shell 介紹：Bash、Zsh 和 Fish | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux Shell 介紹：Bash、Zsh 和 Fish | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux Shell 介紹：Bash、Zsh 和 Fish | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230719.2 ⭐️⭐️ Linux Shells Bash, Zsh, and Fish Explained","title":"Linux Shell 介紹：Bash、Zsh 和 Fish","tag":"202307","desc":""},"relativePath":"202307/20230719.2 ⭐️⭐️ Linux Shells Bash, Zsh, and Fish Explained.md","filePath":"[post].md"}'),p={name:"202307/20230719.2 ⭐️⭐️ Linux Shells Bash, Zsh, and Fish Explained.md"};function u(x,l,f,b,S,m){const i=r("Link");return o(),d("div",null,[l[28]||(l[28]=n('<h1 id="linux-shell-介紹-bash、zsh-和-fish" tabindex="-1">Linux Shell 介紹：Bash、Zsh 和 Fish <a class="header-anchor" href="#linux-shell-介紹-bash、zsh-和-fish" aria-label="Permalink to “Linux Shell 介紹：Bash、Zsh 和 Fish”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/27/152721rd48wwn7xxfkngdw.jpg" alt=""></p><blockquote><p>關於著名的 Linux Shell - Bash、Zsh 和 Fish 的一些註釋和特性。</p></blockquote><p>Linux 之所以強大，是因為它提供了用於與系統進行交互的多功能的命令列界面。在這中情況下，Shell 扮演了用户和 Linux 內核之間的橋樑。本文將探討三種流行的 Linux Shell - Bash、Zsh 和 Fish，並深入瞭解它們的獨特特性和功能。</p><h3 id="理解-linux-shell" tabindex="-1">理解 Linux Shell <a class="header-anchor" href="#理解-linux-shell" aria-label="Permalink to “理解 Linux Shell”">​</a></h3><h4 id="什麼是-shell" tabindex="-1">什麼是 Shell？ <a class="header-anchor" href="#什麼是-shell" aria-label="Permalink to “什麼是 Shell？”">​</a></h4><p>Shell 是一個命令列解釋器，允許你通過文本命令與操作系統進行交互。它接收你的輸入，處理它，並與 Linux 內核通信以執行所請求的操作。最後，它會給你一個輸出。</p><p>（LCTT 譯註：“Shell” 一詞大約取自其“界面”、“外殼”的含義。）</p><p>Shell 在 Linux 中起着至關重要的作用，因為它們使用户能夠執行各種任務，從簡單的文件導航到複雜的系統管理任務。不同的 Shell 提供各種功能，因此選擇適合你工作流程的 Shell 至關重要。</p><h3 id="bash" tabindex="-1">Bash <a class="header-anchor" href="#bash" aria-label="Permalink to “Bash”">​</a></h3>',10)),h("p",null,[e(i,{href:"https://www.gnu.org/software/bash/"},{default:a(()=>[...l[0]||(l[0]=[s("Bash",-1)])]),_:1}),l[1]||(l[1]=s("，全稱 “Bourne Again SHell”，是 Linux 發行版中最廣泛使用的默認 Shell 之一。它以其簡潔和兼容性而聞名，是初學者的優秀選擇。",-1))]),l[29]||(l[29]=n('<h4 id="bash-的特點" tabindex="-1">Bash 的特點 <a class="header-anchor" href="#bash-的特點" aria-label="Permalink to “Bash 的特點”">​</a></h4><p>Bash 具有眾多特性，包括：</p><ul><li>命令歷史：使用箭頭鍵輕鬆訪問先前執行的命令。</li><li><code>Tab</code> 鍵補全：節省時間，讓 Bash 為你自動完成文件名和命令。</li><li>腳本編寫：編寫和運行 Shell 腳本以自動化重複任務。從這個角度來看，它也是一個程序。</li><li>Bash 在大多數 GNU/Linux 系統中默認安裝。</li><li>配置設置存儲在家目錄下的 <code>.bashrc</code> 文件中。</li></ul><p>和其他 Shell 一樣，Bash 有其優點和缺點。使用 Bash 的一些優勢包括廣泛的使用性、詳盡的文檔以及龐大的社區支持。然而，Bash 可能缺乏其他 Shell 中存在的一些現代化特性。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/07/Bash-shell-in-Linux.jpg" alt="Linux 中的 Bash shell"></p><h4 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h4><ul><li>在 Linux 發行版中打開終端。</li><li>輸入 <code>bash --version</code> 檢查是否已安裝 Bash。</li><li>若尚未安裝，使用軟件包管理器安裝 Bash。例如，在 Ubuntu 上，輸入 <code>sudo apt-get install bash</code>。</li><li>對於 Fedora 和基於 RPM 的 Linux，請使用 <code>sudo dnf install bash</code>。</li></ul><h3 id="zsh" tabindex="-1">Zsh <a class="header-anchor" href="#zsh" aria-label="Permalink to “Zsh”">​</a></h3>',8)),h("p",null,[e(i,{href:"https://www.zsh.org/"},{default:a(()=>[...l[2]||(l[2]=[s("Zsh",-1)])]),_:1}),l[3]||(l[3]=s("，全稱 “Z Shell”，是一種強大且功能豐富的 Shell，深受經驗豐富的用户歡迎。它吸取了 Bash 和其他 Shell 的優點，提升了用户體驗。",-1))]),l[30]||(l[30]=h("h4",{id:"zsh-的優勢",tabindex:"-1"},[s("Zsh 的優勢 "),h("a",{class:"header-anchor",href:"#zsh-的優勢","aria-label":"Permalink to “Zsh 的優勢”"},"​")],-1)),l[31]||(l[31]=h("p",null,"Zsh 提供了幾個優勢，包括：",-1)),h("ul",null,[l[10]||(l[10]=h("li",null,[s("高級自動補全：Zsh 在 Bash 的基礎上提供了更多上下文感知的建議，超越了簡單的 "),h("code",null,"Tab"),s(" 鍵補全。")],-1)),l[11]||(l[11]=h("li",null,[s("當你按下 "),h("code",null,"Tab"),s(" 鍵時，Zsh 會顯示可能的值以供選擇，同時進行自動補全。")],-1)),l[12]||(l[12]=h("li",null,"插件支持：通過社區中提供的各種插件，擴展 Zsh 的功能。",-1)),h("li",null,[l[5]||(l[5]=s("這裏有一個 ",-1)),e(i,{href:"https://github.com/unixorn/awesome-zsh-plugins"},{default:a(()=>[...l[4]||(l[4]=[s("龐大的 Zsh 主題集合",-1)])]),_:1}),l[6]||(l[6]=s("。",-1))]),h("li",null,[l[8]||(l[8]=s("你還可以使用 ",-1)),e(i,{href:"https://www.debugpoint.com/oh-my-zsh-powerlevel10k/"},{default:a(()=>[...l[7]||(l[7]=[s("Oh My Zsh 腳本",-1)])]),_:1}),l[9]||(l[9]=s(" 進行廣泛的自定義。",-1))])]),l[32]||(l[32]=n('<p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/After-applying-settings-in-powerlevel10k-zsh-theme.jpg" alt="應用 powerlevel10k zsh 主題後的效果"></p><p>Zsh 的複雜性可能使新手感到不知所措，其豐富的配置選項可能會使初學者感到困惑。</p><p>以下是安裝 Zsh 的方法：</p><ul><li>在 Linux 發行版中打開終端。</li><li>輸入 <code>zsh --version</code> 檢查是否已安裝 Zsh。</li><li>如果尚未安裝，請使用軟件包管理器安裝 Zsh。</li><li>例如，在 Ubuntu 上，輸入 <code>sudo apt-get install zsh</code>。</li><li>對於 Fedora 和基於 RPM 的發行版，輸入 <code>sudo dnf install zsh</code>。</li></ul><h3 id="fish-shell" tabindex="-1">Fish Shell <a class="header-anchor" href="#fish-shell" aria-label="Permalink to “Fish Shell”">​</a></h3>',5)),h("p",null,[e(i,{href:"https://fishshell.com/"},{default:a(()=>[...l[13]||(l[13]=[s("Fish",-1)])]),_:1}),l[14]||(l[14]=s("，全稱 “Friendly Interactive SHell”，着重於用户友好性和易用性。它擁有現代、直觀的界面，特別適合新的 Linux 用户。",-1))]),l[33]||(l[33]=n('<h4 id="fish-的獨特特性" tabindex="-1">Fish 的獨特特性 <a class="header-anchor" href="#fish-的獨特特性" aria-label="Permalink to “Fish 的獨特特性”">​</a></h4><p>Fish 的獨特之處在於：</p><ul><li>語法高亮：使用彩色標記文本來區分命令、選項和參數。</li><li>自動建議：Fish 根據你的歷史記錄和當前輸入智能地建議命令。</li><li>Fish 被設計為開箱即用的高效工具。但是，你可以通過創建 <code>~/.config/fish/config.fish</code> 文件並添加自定義配置來進一步個性化它。</li></ul><p>雖然 Fish 在用户友好性方面表現出色，但其獨特的設計可能並不適合所有人。一些高級用户可能會發現某些功能在高級使用方面有所限制。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/07/Fish-Shell.jpg" alt="Fish Shell"></p><h4 id="fish-shell-的安裝" tabindex="-1">Fish Shell 的安裝 <a class="header-anchor" href="#fish-shell-的安裝" aria-label="Permalink to “Fish Shell 的安裝”">​</a></h4><ul><li>在 Linux 發行版中打開終端。</li><li>輸入 <code>fish --version</code> 檢查是否已安裝 Fish。</li><li>如果尚未安裝，請使用軟件包管理器安裝 Fish。例如，在 Ubuntu 上，輸入 <code>sudo apt-get install fish</code>。</li><li>對於 Fedora 和其他基於 RPM 的發行版，輸入 <code>sudo dnf install fish</code>。</li></ul><h3 id="bash、zsh-和-fish-的比較" tabindex="-1">Bash、Zsh 和 Fish 的比較 <a class="header-anchor" href="#bash、zsh-和-fish-的比較" aria-label="Permalink to “Bash、Zsh 和 Fish 的比較”">​</a></h3><p>為了幫助你決定哪種 Shell 適合你的需求，讓我們從各個方面比較這三個流行選擇：</p><h4 id="性能與速度" tabindex="-1">性能與速度 <a class="header-anchor" href="#性能與速度" aria-label="Permalink to “性能與速度”">​</a></h4><p>Bash 以其速度和高效性而聞名，適用於資源受限的系統。Zsh 雖然稍慢一些，但其廣泛的功能和能力彌補了這一點。作為更具交互性的 Shell，Fish Shell 可能會略微降低性能，但提供了愉快的用户體驗。</p><h4 id="用户界面和體驗" tabindex="-1">用户界面和體驗 <a class="header-anchor" href="#用户界面和體驗" aria-label="Permalink to “用户界面和體驗”">​</a></h4><p>Bash 的界面簡單明瞭，非常適合初學者，而 Zsh 和 Fish 提供了更引人注目和交互式的界面。Zsh 的高級自動補全和 Fish 的語法高亮為用户創造了視覺上的吸引力。</p><h4 id="可定製性和插件" tabindex="-1">可定製性和插件 <a class="header-anchor" href="#可定製性和插件" aria-label="Permalink to “可定製性和插件”">​</a></h4><p>Zsh 在可定製性方面表現出色，允許用户對其 Shell 環境進行微調。通過龐大的插件集合，Zsh 提供了無與倫比的可擴展性。Fish 則採取了更有主見的方式，專注於開箱即用的可用性，這可能對某些用户有所限制。</p><h3 id="選擇合適的-shell" tabindex="-1">選擇合適的 Shell <a class="header-anchor" href="#選擇合適的-shell" aria-label="Permalink to “選擇合適的 Shell”">​</a></h3><p>選擇合適的 Shell 與你的具體需求和經驗水平密切相關。</p><p>如果你是 Linux 的新手並且更喜歡簡單、無花俏的體驗，Bash 是一個極好的起點。它的易用性和詳盡的文檔使其非常適合初學者。</p><p>對於希望更多掌握控制權並願意花時間進行定製的經驗豐富的用户來説，Zsh 強大的功能和插件提供了一個令人興奮和動態的環境。</p><p>如果你對自動化任務和編寫複雜的 Shell 腳本感興趣，Bash 在 Linux 生態系統中的廣泛應用和全面支持使其成為一個可靠的選擇。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>Bash、Zsh 和 Fish 各有其優勢，滿足不同用户偏好。如果你剛接觸 Linux，Bash 的簡單性使其成為一個極好的起點。精通用户和那些尋求定製化的用户可能會覺得 Zsh 更吸引人，而 Fish 的用户友好設計則適合尋求直觀界面的初學者。最終，選擇權在你手中，探索這些 Shell 將帶來更高效和愉悦的 Linux 使用體驗。</p><p>你最喜歡的 Shell 是什麼？在下方的評論框中告訴我。</p><p><em>（題圖：MJ/b6490b57-63bd-4fdd-bd3f-bf6d4aef1c4a）</em></p><hr>',25)),h("p",null,[l[16]||(l[16]=s("via: ",-1)),e(i,{href:"https://www.debugpoint.com/linux-shells/"},{default:a(()=>[...l[15]||(l[15]=[s("https://www.debugpoint.com/linux-shells/",-1)])]),_:1})]),h("p",null,[l[20]||(l[20]=s("作者：",-1)),e(i,{href:"https://www.debugpoint.com/author/admin1/"},{default:a(()=>[...l[17]||(l[17]=[s("Arindam",-1)])]),_:1}),l[21]||(l[21]=s(" 選題：",-1)),e(i,{href:"https://github.com/lkxed/"},{default:a(()=>[...l[18]||(l[18]=[s("lkxed",-1)])]),_:1}),l[22]||(l[22]=s(" 譯者：ChatGPT 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:a(()=>[...l[19]||(l[19]=[s("wxy",-1)])]),_:1})]),h("p",null,[l[25]||(l[25]=s("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...l[23]||(l[23]=[s("LCTT",-1)])]),_:1}),l[26]||(l[26]=s(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:a(()=>[...l[24]||(l[24]=[s("Linux中國",-1)])]),_:1}),l[27]||(l[27]=s(" 榮譽推出",-1))])])}const B=t(p,[["render",u]]);export{w as __pageData,B as default};
